head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "ULDFIL59400";
scwin.pageIndex = 1;
scwin.pageItemCnt = 15;

// 원본 : ULDFIL59400 코스닥 전문평가신청 목록 (/ui/lst/lstinvstg/ULDFIL59400.xml)

/*
 * 화면 동작
 * 1. 화면 로딩시 신청 목록을 페이징 조회
 * 2. 「페이지당 건수」 변경시 첫 페이지부터 다시 조회
 * 3. 신청명 클릭시 처리상태에 따라 수정 또는 조회 모드로 상세 화면 이동
 * 4. 처리상태가 작성중·반려·보완요청이면 「제출」, 제출완료·접수완료면 「수정요청」 버튼을 표시
 * 5. 「신규작성」 클릭시 작성 화면으로 이동
 */

// 페이징 상태값

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        // 초기화 함수
        await scwin.init();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "jldfil59400-ref.onpageload" });
    }
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init = async function () {
    // 통신 전 : paging 설정
    scwin.setPagingInfo();

    // 목록 조회
    await scwin.searchList(1);
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_reg_onclick
 * @description 신규작성 버튼 클릭. 작성화면을 신규 모드로 연다.
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_reg_onclick = function (e) {
    try {
        $c.win.moveUrl("/ui/sample/template/ULDFIL52100.xml", { loadTp : "0" });
    } catch (ex) {
        $c.exception.handleError(ex, { context : "jldfil59400-ref.btn_reg_onclick" });
    }
};

/**
 * @method
 * @name btn_regLarge_onclick
 * @description 대형 작성화면으로 이동한다.
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_regLarge_onclick = function (e) {
    try {
        $c.win.moveUrl("/ui/sample/template/ULDFIL59410.xml", {});
    } catch (ex) {
        $c.exception.handleError(ex, { context : "jldfil59400-ref.btn_regLarge_onclick" });
    }
};

/**
 * @method
 * @name grd_main_oncellclick
 * @description 그리드 셀 클릭. 컬럼별로 동작을 나눈다.
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_main_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const rowData = dlt_main.getRowJSON(rowIndex);

        // 명칭 클릭 -> 상세 이동
        if (columnId === "aplcNm") {
            scwin.goDetail(rowData);
            return;
        }

        // 버튼 컬럼 클릭 -> 상태에 따라 처리
        if (columnId === "btnCol") {
            await scwin.processRow(rowData);
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "jldfil59400-ref.grd_main_oncellclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name searchList
 * @description 목록을 페이징 조회한다.
 * @param {*} pageIndex pageIndex
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.searchList = async function (pageIndex) {
    scwin.pageIndex = pageIndex;

    dma_search.set("page", scwin.pageIndex);
    dma_search.set("size", scwin.pageItemCnt);

    const sbmOptions = {
        id : "sbm_searchList",
        method : "get",
        action : "/api/listing/listinvstg/specialized-evaluation/select-list-paging",
        ref : "dma_search",
        target : "dlt_main=body.content",
        gridview : "grd_main", // 조회 전 그리드 초기화
        isProcessMsg : false
    };

    // 통신 오류 시 reject 되므로 catch 로 받는다. 사용자 안내는 공통 오류 핸들러가 한다.
    const result = await $c.sbm.executeDynamic(sbmOptions);

    // 통신 후 : paging 설정
    scwin.setPagingInfo(result);

    // 상태에 따라 버튼 컬럼 라벨을 채운다.
    scwin.setButtonLabel();
};

/**
 * @method
 * @name submitRow
 * @description 목록에서 바로 처리하는 API 호출. 확인 -> 호출 -> 결과판정 -> 재조회 순서.
 * @param {*} rowData rowData
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.submitRow = async function (rowData) {
    if (!await $c.win.confirm($c.data.getMessage("com_crud_0198", "제출"))) return;

    const sbmOptions = {
        id : "sbm_submitRow",
        method : "post",
        action : "/api/listing/listinvstg/specialized-evaluation/appl-submit",
        isProcessMsg : false
    };

    const requestData = {
        aplcNo : rowData.aplcNo
    };

    const result = await $c.sbm.executeDynamic(sbmOptions, requestData);

    // 통신 오류는 공통 오류 핸들러가 안내하므로 화면은 중단만 한다.
    if ($c.util.isEmpty(result.responseJSON)) return;

    if (!result.responseJSON.success) {
        $c.win.alert($c.data.getMessage("com_complete_0151", "제출"));
        return;
    }

    await $c.win.alert($c.data.getMessage("com_complete_0150", "제출"));

    // 처리 후 첫 페이지부터 재조회
    await scwin.searchList(1);
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name setPagingInfo
 * @description Paging 컴포넌트 설정. 통신 전(전체건수 0)과 통신 후 모두 호출한다.
 * @param {*} result result
 * @returns {void}
 * @hidden N
 */
scwin.setPagingInfo = function (result = {}) {
    const pagingInfo = {
        pageType : "P",                          // S/P/A Default=P
        rowNumVisble : "grd_main|asc",           // gridView 에 rowNumVisible 값 설정
        maxRowNum : 50,                          // gridView 에 최대 visibleRowNum 값 설정
        pageListId : "pgl_list",                 // 페이지 리스트 아이디
        pageFunction : "scwin.searchList",       // 페이징 처리 함수
        currentPage : scwin.pageIndex,           // 현재 페이지
        recordCountPerPage : scwin.pageItemCnt,  // 한 페이지 건수. 반드시 넘길 것 (아래 주석 참고)
        totalCountId : "txt_totalCnt",           // total count 출력 아이디
        pageSize : 10                            // 페이징 시 출력해줄 페이지 번호 개수
    };

    /* recordCountPerPage 를 빠뜨리면 공통 함수가 기본값 10 을 쓴다.
     * 페이지 수는 Math.ceil(전체건수 / recordCountPerPage) 로 계산되므로,
     * 화면에서 50건씩 조회해도 10 으로 나눠 페이지 번호가 과도하게 생긴다.
     * 행 번호 시작값((현재페이지-1) * recordCountPerPage) 도 같이 틀어진다. */
    $c.sbm.setPagingInfo(pagingInfo, "dma_paging", result.responseJSON?.body?.totalCount || 0);
};

/**
 * @method
 * @name goDetail
 * @description 상세화면으로 이동한다. 조회/수정 모드는 상태로 판단해 넘긴다.
 * @param {*} rowData rowData
 * @returns {void}
 * @hidden N
 */
scwin.goDetail = function (rowData) {
    const param = {
        aplcNo : rowData.aplcNo,
        loadTp : scwin.isWritable(rowData.procsStatCd) ? "1" : "8" // 1:수정, 8:조회
    };

    $c.win.moveUrl("/ui/sample/template/ULDFIL52100.xml", param);
};

/**
 * @method
 * @name processRow
 * @description 버튼 컬럼 클릭 처리. 상태에 따라 서로 다른 동작으로 분기한다.
 * @param {*} rowData rowData
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.processRow = async function (rowData) {
    if (scwin.isWritable(rowData.procsStatCd)) {
        await scwin.submitRow(rowData);
        return;
    }

    if (scwin.isModifyRequestable(rowData.procsStatCd)) {
        await scwin.openProcessPopup(rowData);
    }
};

/**
 * @method
 * @name openProcessPopup
 * @description 처리 팝업을 열고, 닫힌 뒤 목록을 다시 읽는다.
 * @param {*} rowData rowData
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.openProcessPopup = async function (rowData) {
    const param = {
        aplcNo : rowData.aplcNo
    };

    const options = {
        id : "ULDFIL59411",
        popupName : "수정요청",
        width : 900,
        height : 400,
        frameModal : "top"
    };

    await $c.win.openPopup("/ui/sample/template/ULDFIL59411.xml", options, param);

    // 팝업에서 처리가 일어났을 수 있으므로 반환값과 무관하게 재조회한다.
    await scwin.searchList(1);
};

/**
 * @method
 * @name isWritable
 * @description 작성 가능 상태인지 판단한다. 상태 판정은 함수로 묶어 화면 곳곳의 조건문을 줄인다.
 * @param {String} procsStatCd procsStatCd
 * @returns {void}
 * @hidden N
 */
scwin.isWritable = function (procsStatCd) {
    // 30 작성중 · 35 반려 · 37 보완요청. 아직 화면에서 고칠 수 있는 상태다.
    return ["30", "35", "37"].includes(procsStatCd);
};

/**
 * @method
 * @name isModifyRequestable
 * @description 수정요청 가능 상태인지 반환한다.
 * @param {String} procsStatCd procsStatCd
 * @returns {void}
 * @hidden N
 */
scwin.isModifyRequestable = function (procsStatCd) {
    // 33 제출완료 · 36 접수완료. 제출한 뒤라 수정요청으로만 고칠 수 있다.
    return ["33", "36"].includes(procsStatCd);
};

/**
 * @method
 * @name setButtonLabel
 * @description 상태에 따라 버튼 컬럼의 라벨과 노출 여부를 정한다.
 * @returns {void}
 * @hidden N
 */
scwin.setButtonLabel = function () {
    const rowCount = dlt_main.getRowCount();

    dlt_main.setBroadcast(false);
    for (let i = 0; i < rowCount; i++) {
        const procsStatCd = dlt_main.getCellData(i, "procsStatCd");

        let label = "";

        if (scwin.isWritable(procsStatCd)) {
            label = "제출";
        } else if (scwin.isModifyRequestable(procsStatCd)) {
            label = "수정요청";
        }

        dlt_main.setCellData(i, "btnCol", label);

        // 라벨이 없는 행은 빈 버튼이 남으므로 감춘다.
        // display 가 아니라 visibility 를 쓴다. 셀 높이가 무너지지 않는다.
        grd_main.setCellStyle(i, "btnCol", "visibility", $c.util.isEmpty(label) ? "hidden" : "visible");
    }
    dlt_main.setBroadcast(true, true);
};
